/* aesthetic panel v2.22.0 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-space-6: 2em;
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

.ae-panel {
background: var(--ae-surface);
  padding: var(--ae-space-6);
  box-shadow:
    0 1px 2px rgba(0, 0, 0, 0.04),
    0 8px 28px rgba(0, 0, 0, 0.06);
}

.dark .ae-panel,
[data-ae-mode='dark'] .ae-panel {
background: var(--ae-wash);
  box-shadow: none;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) .ae-panel {
  background: var(--ae-wash);
      box-shadow: none;
  }
}
